def e(x): return html.escape(str(x), quote=True)
def p(x): return '<p>' + x + '</p>'
def link(title, url): return f'<a href="{e(url)}">{e(title)}</a>'
def git(path, line=None): return link(path + (':' + str(line) if line else ''), GH + path + ('#L' + str(line) if line else ''))
def table(head, rows):
    return '<div class="table-wrap" tabindex="0"><table><thead><tr>' + ''.join('<th>' + x + '</th>' for x in head) + '</tr></thead><tbody>' + ''.join('<tr>' + ''.join('<td>' + str(x) + '</td>' for x in row) + '</tr>' for row in rows) + '</tbody></table></div>'
def formula(x): return '<pre class="codeformula"><code>' + e(x) + '</code></pre>'


